window.RP_SESSION={"id":"S-d49aee8a3ff9","messages":[{"id":"RP-0159770","time":"2026-05-20T00:20:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"팔세테 마을에서 있었던 일 이후,","characters":["P-b15cb9756a04"]},{"id":"RP-0159771","time":"2026-05-20T00:21:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"개큰일에 휘말려버린 기분이다.","characters":["P-b15cb9756a04"]},{"id":"RP-0159772","time":"2026-05-20T00:23:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"언제나 건성건성.\n\n하던대로 발끝만 담그며 시키는 일만 하다가.\n\n너무 일이 커지면 슬슬 발을 빼는 거였는데.","characters":["P-b15cb9756a04"]},{"id":"RP-0159773","time":"2026-05-20T00:24:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"발 뺄 타이밍을 놓쳤나?\n\n아니면 그 주점을 터트려버렸을 때 허벅지까지 쑥 빠져버렸나?","characters":["P-b15cb9756a04"]},{"id":"RP-0159774","time":"2026-05-20T00:24:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"게다가 이제 내가 내가 정식 길드원이라니.","characters":["P-b15cb9756a04"]},{"id":"RP-0159775","time":"2026-05-20T00:25:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"왜 그랬을까?","characters":["P-b15cb9756a04"]},{"id":"RP-0159776","time":"2026-05-20T00:25:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그 토르번 녀석의 숨겨진 쌍둥이를 개꿀잼 막장 소설처럼 마구 포장해서","characters":["P-b15cb9756a04"]},{"id":"RP-0159777","time":"2026-05-20T00:26:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"개큰뉴스를 발표하면 끝나는 일이었는데.","characters":["P-b15cb9756a04"]},{"id":"RP-0159778","time":"2026-05-20T00:27:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"토르번이 지 입으로 스스로 자신의 죄와, 가문에 대한 이야기를 게시판에 알려도 된다고 했을 땐, 일종의 책임감과 함께\n\n머리끝까지 차올랐던 배덕감과 흥미가 팍 식어버렸다.","characters":["P-b15cb9756a04"]},{"id":"RP-0159779","time":"2026-05-20T00:27:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"나는 이 길드에 계속 있어도 되는 걸까?\n\n내가 소속감이나, 사명감 같은 게 있기는 할까?","characters":["P-b15cb9756a04"]},{"id":"RP-0159780","time":"2026-05-20T00:27:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"타냐가 느끼던 감정은 이른바, 권태에 대한 권태감이었다.","characters":["P-b15cb9756a04"]},{"id":"RP-0159781","time":"2026-05-20T00:28:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"아무래도 ㅈ됐다.\n그것이 내가 심사숙고 끝에 내린 결론이다.\n나는 ㅈ됐다.","characters":["P-b15cb9756a04"]},{"id":"RP-0159782","time":"2026-05-20T00:28:00+09:00","room":"RP","name":"타냐 잉게누스","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b15cb9756a04"]},{"id":"RP-0159783","time":"2026-05-20T00:28:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
